* { margin: 0; padding: 0; box-sizing: border-box; }

:root {
  --accent: #6fd3ff;
  --accent-dim: rgba(111, 211, 255, 0.25);
  --panel: rgba(7, 13, 22, 0.78);
  --warn: #ff8c3a;
}

html, body {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #060a10;
  font-family: "Segoe UI", "Helvetica Neue", Arial, sans-serif;
  color: #dce8f2;
  user-select: none;
}

#gl { position: fixed; inset: 0; display: block; }

.hidden { display: none !important; }

/* ---------- Menu ---------- */

#menu {
  position: fixed;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 4vh 4vw;
  z-index: 10;
}

#menu h1 {
  font-size: clamp(28px, 4.2vw, 54px);
  font-weight: 800;
  letter-spacing: 0.35em;
  text-shadow: 0 0 24px rgba(111, 211, 255, 0.55);
  margin-bottom: 6px;
}

#menu .subtitle {
  letter-spacing: 0.5em;
  font-size: 12px;
  color: var(--accent);
  margin-bottom: 3vh;
  text-transform: uppercase;
}

.menu-body {
  display: flex;
  gap: 24px;
  width: min(1180px, 92vw);
  flex: 1;
  min-height: 0;
  align-items: stretch;
}

.cards {
  display: flex;
  flex-direction: column;
  gap: 14px;
  width: 300px;
  flex-shrink: 0;
}

.plane-card {
  background: var(--panel);
  border: 1px solid var(--accent-dim);
  border-radius: 10px;
  padding: 14px 16px;
  cursor: pointer;
  transition: border-color 0.15s, transform 0.15s, box-shadow 0.15s;
}

.plane-card:hover { transform: translateX(4px); }

.plane-card.active {
  border-color: var(--accent);
  box-shadow: 0 0 18px rgba(111, 211, 255, 0.25), inset 0 0 24px rgba(111, 211, 255, 0.06);
}

.plane-card .card-name { font-size: 17px; font-weight: 700; letter-spacing: 0.06em; }
.plane-card .card-type { font-size: 11px; letter-spacing: 0.25em; text-transform: uppercase; margin-top: 3px; }

.menu-spacer { flex: 1; }

.stats-panel {
  background: var(--panel);
  border: 1px solid var(--accent-dim);
  border-radius: 10px;
  padding: 22px 26px;
  width: 360px;
  flex-shrink: 0;
  margin-left: auto;
  display: flex;
  flex-direction: column;
}

.stats-panel h2 { font-size: 22px; letter-spacing: 0.05em; }
.stats-panel .stat-type { font-size: 11px; letter-spacing: 0.3em; text-transform: uppercase; color: var(--accent); margin: 4px 0 10px; }
.stats-panel .stat-desc { font-size: 13px; line-height: 1.5; color: #9fb4c6; margin-bottom: 16px; min-height: 58px; }

.bar-row { display: flex; align-items: center; gap: 10px; margin-bottom: 9px; }
.bar-label { width: 86px; font-size: 11px; letter-spacing: 0.18em; color: #8fa6ba; }
.bar-track {
  flex: 1;
  height: 9px;
  background: rgba(255, 255, 255, 0.07);
  border-radius: 5px;
  overflow: hidden;
}
.bar-fill {
  height: 100%;
  border-radius: 5px;
  background: linear-gradient(90deg, #2e8fc4, var(--accent));
  transition: width 0.35s ease;
}

.spec-table { width: 100%; border-collapse: collapse; margin: 14px 0 18px; }
.spec-table td { font-size: 12px; padding: 4px 0; border-bottom: 1px solid rgba(255, 255, 255, 0.06); }
.spec-table td:first-child { color: #8fa6ba; letter-spacing: 0.08em; }
.spec-table td:last-child { text-align: right; font-weight: 600; }

#start-btn {
  margin-top: auto;
  padding: 14px;
  font-size: 16px;
  font-weight: 800;
  letter-spacing: 0.3em;
  color: #081018;
  background: linear-gradient(180deg, #ffb35c, var(--warn));
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: filter 0.15s, transform 0.1s;
}
#start-btn:hover { filter: brightness(1.12); }
#start-btn:active { transform: scale(0.98); }

.controls-hint {
  margin-top: 2.4vh;
  font-size: 12px;
  letter-spacing: 0.08em;
  color: #7e94a8;
}

/* ---------- HUD ---------- */

#hud { position: fixed; inset: 0; pointer-events: none; z-index: 5; }

.hud-panel {
  position: absolute;
  background: var(--panel);
  border: 1px solid var(--accent-dim);
  border-radius: 8px;
  padding: 10px 14px;
}

#hud-top-left { top: 18px; left: 18px; }
.hud-label { font-size: 13px; letter-spacing: 0.2em; line-height: 1.7; }
.hud-label span { color: var(--accent); font-weight: 700; }

#radar {
  position: absolute;
  top: 18px;
  right: 18px;
  border-radius: 50%;
  border: 1px solid var(--accent-dim);
  background: rgba(7, 13, 22, 0.7);
}

#hud-bottom-left { bottom: 18px; left: 18px; min-width: 190px; }
.hud-row { display: flex; align-items: center; gap: 8px; font-size: 14px; line-height: 1.8; }
.hud-key { width: 36px; font-size: 11px; letter-spacing: 0.15em; color: #8fa6ba; }
.hud-unit { font-size: 10px; color: #8fa6ba; }
.hud-row span:nth-child(2) { font-weight: 700; min-width: 48px; font-variant-numeric: tabular-nums; }
.hud-bar { flex: 1; height: 8px; background: rgba(255,255,255,0.08); border-radius: 4px; overflow: hidden; }
.hud-bar-fill { height: 100%; width: 70%; background: var(--warn); border-radius: 4px; }

#hud-hp-wrap {
  position: absolute;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  width: 300px;
  height: 14px;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid var(--accent-dim);
  border-radius: 7px;
  overflow: hidden;
}
#hud-hp { height: 100%; width: 100%; background: #58d68d; transition: width 0.15s, background 0.3s; }

#crosshair {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 26px;
  height: 26px;
  transform: translate(-50%, -50%);
  border: 1.5px solid rgba(111, 211, 255, 0.9);
  border-radius: 50%;
  box-shadow: 0 0 8px rgba(111, 211, 255, 0.35);
}
#crosshair::after {
  content: "";
  position: absolute;
  top: 50%; left: 50%;
  width: 3px; height: 3px;
  transform: translate(-50%, -50%);
  background: var(--accent);
  border-radius: 50%;
}

#hitmarker {
  position: absolute;
  top: 50%; left: 50%;
  transform: translate(-50%, -50%);
  font-size: 28px;
  font-weight: 800;
  color: #fff;
  opacity: 0;
  text-shadow: 0 0 6px #ffd27a;
}

#vignette {
  position: absolute;
  inset: 0;
  opacity: 0;
  background: radial-gradient(ellipse at center, transparent 45%, rgba(255, 30, 20, 0.55) 100%);
}

#hud-hint {
  position: absolute;
  bottom: 60px;
  left: 50%;
  transform: translateX(-50%);
  font-size: 11px;
  letter-spacing: 0.08em;
  color: rgba(220, 232, 242, 0.75);
  background: var(--panel);
  padding: 6px 14px;
  border-radius: 6px;
  transition: opacity 1s;
  white-space: nowrap;
}

/* ---------- Banner / fade ---------- */

#banner {
  position: fixed;
  top: 26%;
  left: 50%;
  transform: translateX(-50%);
  text-align: center;
  z-index: 8;
  pointer-events: none;
}
#banner-title {
  font-size: clamp(30px, 4.5vw, 58px);
  font-weight: 800;
  letter-spacing: 0.4em;
  text-shadow: 0 0 30px rgba(111, 211, 255, 0.6);
}
#banner-sub { font-size: 15px; letter-spacing: 0.45em; margin-top: 10px; color: var(--accent); }
#banner.red #banner-title { color: #ff6a55; text-shadow: 0 0 30px rgba(255, 80, 60, 0.6); }
#banner.red #banner-sub { color: #ff9c8c; }

#fade {
  position: fixed;
  inset: 0;
  background: #000;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.35s ease;
  z-index: 50;
}

