import * as THREE from 'three';

export const G = 9.81;

const _fwd = new THREE.Vector3();
const _q = new THREE.Quaternion();
const _axis = new THREE.Vector3();

/**
 * Simplified flight dynamics shared by player and AI planes.
 * Realistic limitations modeled:
 *  - top speed from thrust/drag equilibrium (drag ~ v^2)
 *  - stall below stallSpeed: nose drops, controls go mushy, plane sinks
 *  - turn rate limited by airframe G limit (rate = G·g / v, so fast = wide turns)
 *  - climbing bleeds speed, diving gains it
 *  - thrust fades above the service ceiling
 */
export class FlightBody {
  constructor(spec) {
    this.spec = spec;
    this.pos = new THREE.Vector3();
    this.quat = new THREE.Quaternion();
    this.vel = new THREE.Vector3();
    this.speed = spec.maxSpeed * 0.55;
    this.throttle = 0.7;
    this.hp = spec.hp;
    this.maxHp = spec.hp;
    this.fallVel = 0;
  }

  forward(out = _fwd) {
    return out.set(0, 0, -1).applyQuaternion(this.quat);
  }

  up(out) {
    return out.set(0, 1, 0).applyQuaternion(this.quat);
  }

  /** ctl: { pitch (-1..1, + = pull), roll (-1..1, + = right), yaw (-1..1, + = right) } */
  step(dt, ctl) {
    const s = this.spec;
    const fwd = this.forward();

    const ceilingFactor = THREE.MathUtils.clamp(1 - (this.pos.y - s.ceiling) / 1500, 0, 1);
    const dragK = s.thrustAccel / (s.maxSpeed * s.maxSpeed);
    const accel =
      this.throttle * s.thrustAccel * ceilingFactor -
      dragK * this.speed * this.speed -
      G * fwd.y * 0.9;
    this.speed = Math.max(0, this.speed + accel * dt);

    const auth = THREE.MathUtils.clamp(
      (this.speed - s.stallSpeed * 0.5) / (s.stallSpeed * 0.8), 0.05, 1
    );
    const gLimitedRate = (s.maxG * G) / Math.max(this.speed, 25);
    const pitchRate = Math.min(s.pitchRate, gLimitedRate) * auth;
    const rollRate = s.rollRate * (0.3 + 0.7 * auth);
    const yawRate = s.yawRate * auth;

    this.quat.multiply(_q.setFromAxisAngle(_axis.set(1, 0, 0), ctl.pitch * pitchRate * dt));
    this.quat.multiply(_q.setFromAxisAngle(_axis.set(0, 0, 1), -ctl.roll * rollRate * dt));
    this.quat.multiply(_q.setFromAxisAngle(_axis.set(0, 1, 0), -ctl.yaw * yawRate * dt));
    this.quat.normalize();

    const stall = THREE.MathUtils.clamp((s.stallSpeed - this.speed) / s.stallSpeed, 0, 1);
    if (stall > 0) {
      this.quat.multiply(_q.setFromAxisAngle(_axis.set(1, 0, 0), -stall * 0.9 * dt));
    }

    this.forward(fwd);
    this.vel.copy(fwd).multiplyScalar(this.speed);
    this.vel.y -= stall * 40;
    this.pos.addScaledVector(this.vel, dt);
  }

  /** Uncontrolled death spiral: rolls, noses over, gravity wins. */
  stepDying(dt) {
    this.quat.multiply(_q.setFromAxisAngle(_axis.set(0, 0, 1), 2.4 * dt));
    this.quat.multiply(_q.setFromAxisAngle(_axis.set(1, 0, 0), -0.55 * dt));
    this.speed = Math.max(this.speed * (1 - 0.25 * dt), 50);
    this.fallVel = Math.min(this.fallVel + G * 1.7 * dt, 130);
    const fwd = this.forward();
    this.vel.copy(fwd).multiplyScalar(this.speed);
    this.vel.y -= this.fallVel;
    this.pos.addScaledVector(this.vel, dt);
  }
}

