    this.quat.multiply(_q.setFromAxisAngle(_axis.set(0, 1, 0), -ctl.yaw * yawRate * dt));
    this.quat.normalize();

    const stall = THREE.MathUtils.clamp((s.stallSpeed - this.speed) / s.stallSpeed, 0, 1);
    if (stall > 0) {
      this.quat.multiply(_q.setFromAxisAngle(_axis.set(1, 0, 0), -stall * 0.9 * dt));
    }

    this.forward(fwd);
    this.vel.copy(fwd).multiplyScalar(this.speed);
    this.vel.y -= stall * 40;
    this.pos.addScaledVector(this.vel, dt);
  }

  /** Uncontrolled death spiral: rolls, noses over, gravity wins. */
  stepDying(dt) {
    this.quat.multiply(_q.setFromAxisAngle(_axis.set(0, 0, 1), 2.4 * dt));
    this.quat.multiply(_q.setFromAxisAngle(_axis.set(1, 0, 0), -0.55 * dt));
    this.speed = Math.max(this.speed * (1 - 0.25 * dt), 50);
    this.fallVel = Math.min(this.fallVel + G * 1.7 * dt, 130);
    const fwd = this.forward();
    this.vel.copy(fwd).multiplyScalar(this.speed);
    this.vel.y -= this.fallVel;
    this.pos.addScaledVector(this.vel, dt);
  }
}

