    ],
  },
  {
    id: 'mustang',
    name: 'P-51 "Mustang"',
    type: 'Propeller Plane',
    desc: 'WWII piston-engine warbird. Slow but razor-agile — its low stall speed lets it out-turn anything in a knife fight. Four wing-mounted machine guns.',
    maxSpeed: 165, stallSpeed: 38, thrustAccel: 28, maxG: 7,
    pitchRate: 2.0, rollRate: 2.3, yawRate: 0.6, ceiling: 3200,
    hp: 85, gunDamage: 4, fireInterval: 0.11, bulletSpeed: 750,
    guns: [[-3.4, -0.35, -0.8], [-2.6, -0.35, -0.8], [2.6, -0.35, -0.8], [3.4, -0.35, -0.8]],
    tracerColor: 0xffe9a0,
    camDist: 16, camHeight: 4.2,
    bars: { SPEED: 0.45, AGILITY: 0.95, ARMOR: 0.5, FIREPOWER: 0.65 },
    specs: [
      ['Top speed', '594 km/h'],
      ['Stall speed', '137 km/h'],
      ['Service ceiling', '3,200 m'],
      ['G limit', '7.0 G'],
      ['Armament', '4× .50 cal MG'],
      ['Airframe', '85 HP'],
    ],
  },
  {
    id: 'nighthawk',
    name: 'SW-9 "Nighthawk"',
