    const fin = wing([[0, 1.0], [2.1, -0.6], [2.1, -1.4], [0, -1.6]], 0.14, dark);
    fin.rotation.z = Math.PI / 2 - side * 0.3;
    fin.position.set(side * 0.95, 0.5, 4.5);
    g.add(fin);

    const engine = new THREE.Mesh(new THREE.CylinderGeometry(0.48, 0.42, 2.2, 8).rotateX(Math.PI / 2), dark);
    engine.position.set(side * 0.72, -0.18, 4.4);
    g.add(engine);
  }

  const burner = new THREE.Group();
  for (const side of [-1, 1]) {
    const b = burnerMesh(0.36, 2.2);
    b.position.set(side * 0.72, -0.18, 5.5);
    burner.add(b);
  }
  g.add(burner);
  g.userData.burner = burner;

  return g;
}

function buildMustang() {
  const g = new THREE.Group();
  const silver = mat(0xc9ced6);
  const red = mat(0xc23b2e, { emissive: 0x1d0503 });
  const dark = mat(0x3a4148);

  const fus = new THREE.Mesh(new THREE.CylinderGeometry(0.38, 0.74, 7, 10).rotateX(Math.PI / 2), silver);
  fus.position.z = 0.3;
  g.add(fus);

  const cowl = new THREE.Mesh(new THREE.CylinderGeometry(0.74, 0.8, 1.5, 10).rotateX(Math.PI / 2), red);
  cowl.position.z = -3.95;
  g.add(cowl);

  const spinner = new THREE.Mesh(new THREE.ConeGeometry(0.45, 1.1, 10).rotateX(-Math.PI / 2), red);
  spinner.position.z = -5.25;
  g.add(spinner);

  const prop = new THREE.Group();
  const bladeGeo = new THREE.BoxGeometry(0.17, 2.7, 0.08);
  bladeGeo.translate(0, 1.35, 0);
  for (let i = 0; i < 3; i++) {
    const blade = new THREE.Mesh(bladeGeo, dark);
    blade.rotation.z = (i * Math.PI * 2) / 3;
    prop.add(blade);
  }
  const disc = new THREE.Mesh(
    new THREE.CircleGeometry(2.75, 24),
    new THREE.MeshBasicMaterial({
      color: 0xccddee, transparent: true, opacity: 0.1,
      blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide,
    })
  );
  prop.add(disc);
  prop.position.z = -5.0;
  g.add(prop);
  g.userData.prop = prop;

  const wings = wing(
    [[-5.5, 0.3], [0, 1.5], [5.5, 0.3], [5.5, -1.1], [0, -1.9], [-5.5, -1.1]],
    0.24, silver
  );
  wings.position.set(0, -0.32, 0.6);
  g.add(wings);

  const canopy = new THREE.Mesh(new THREE.SphereGeometry(0.55, 10, 8), glassMat());
  canopy.scale.set(0.75, 0.75, 1.6);
  canopy.position.set(0, 0.6, -1.0);
  g.add(canopy);

  const antiGlare = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.1, 2.6), dark);
  antiGlare.position.set(0, 0.66, -2.6);
  g.add(antiGlare);

  const hstab = wing(
    [[-2.1, 0.2], [0, 0.8], [2.1, 0.2], [2.1, -0.6], [0, -0.9], [-2.1, -0.6]],
    0.16, silver
  );
  hstab.position.set(0, 0.1, 3.3);
  g.add(hstab);

  const fin = wing([[0, 1.4], [1.5, 0.1], [1.5, -0.6], [0, -0.9]], 0.15, red);
  fin.rotation.z = Math.PI / 2;
  fin.position.set(0, 0.4, 3.2);
  g.add(fin);

  return g;
}

function buildNighthawk() {
  const g = new THREE.Group();
  const dark = mat(0x2e3440, { metalness: 0.5, roughness: 0.45 });
  const darker = mat(0x222731, { metalness: 0.5 });
  const glow = new THREE.MeshBasicMaterial({ color: 0x36e0ff });

  const wingBody = wing(
    [
      [-8, -2.6], [-2.2, 2.6], [0, 6.8], [2.2, 2.6], [8, -2.6],
      [8, -3.7], [4, -4.3], [0, -3.3], [-4, -4.3], [-8, -3.7],
    ],
    0.6, dark
  );
  g.add(wingBody);

  const hump = new THREE.Mesh(new THREE.SphereGeometry(1.0, 12, 8), darker);
  hump.scale.set(1.25, 0.62, 2.7);
  hump.position.set(0, 0.42, -2.0);
  g.add(hump);

  const canopy = new THREE.Mesh(new THREE.SphereGeometry(0.55, 10, 8), glassMat());
  canopy.scale.set(0.85, 0.55, 1.6);
  canopy.position.set(0, 0.85, -3.2);
  g.add(canopy);

  for (const side of [-1, 1]) {
    const intake = new THREE.Mesh(new THREE.BoxGeometry(1.5, 0.5, 2.4), darker);
    intake.position.set(side * 1.7, 0.45, 0.4);
    g.add(intake);

    const fin = wing([[0, 0.9], [1.3, -0.4], [1.3, -1.0], [0, -1.1]], 0.12, darker);
    fin.rotation.z = Math.PI / 2 - side * 0.45;
    fin.position.set(side * 3.1, 0.35, 2.6);
    g.add(fin);

    // leading-edge light strips
    const strip = new THREE.Mesh(new THREE.BoxGeometry(0.09, 0.09, 5.2), glow);
    strip.position.set(side * 4.1, 0.34, -0.6);
    strip.rotation.y = side * 0.71;
    g.add(strip);

    const tipLight = new THREE.Mesh(new THREE.SphereGeometry(0.16, 6, 6), glow);
    tipLight.position.set(side * 7.8, 0.1, -2.7);
    g.add(tipLight);
  }

  const burner = new THREE.Group();
  for (const side of [-1, 1]) {
    const b = burnerMesh(0.4, 1.8);
    b.material.color.set(0x4ad4ff);
    b.position.set(side * 1.7, 0.3, 1.7);
    burner.add(b);
  }
  g.add(burner);
  g.userData.burner = burner;

  return g;
}

export function buildEnemyModel() {
  const g = new THREE.Group();
  const body = mat(0x565b63);
  const red = mat(0xb8352b, { emissive: 0x2a0703 });
  const dark = mat(0x3a3f47);

  const fus = new THREE.Mesh(new THREE.CylinderGeometry(0.55, 0.7, 7.5, 8).rotateX(Math.PI / 2), body);
  g.add(fus);

  const nose = new THREE.Mesh(new THREE.ConeGeometry(0.7, 2.6, 8).rotateX(-Math.PI / 2), red);
  nose.position.z = -5.0;
  g.add(nose);

  const canopy = new THREE.Mesh(new THREE.SphereGeometry(0.55, 8, 6), glassMat());
  canopy.scale.set(0.8, 0.6, 1.7);
  canopy.position.set(0, 0.55, -2.0);
  g.add(canopy);

  const wings = wing(
    [[-4.9, -1.8], [0, 2.3], [4.9, -1.8], [4.9, -2.7], [0, -2.6], [-4.9, -2.7]],
    0.2, body
  );
  wings.position.set(0, -0.1, 1.0);
  g.add(wings);

  for (const side of [-1, 1]) {
    const tip = new THREE.Mesh(new THREE.BoxGeometry(0.45, 0.12, 1.2), red);
    tip.position.set(side * 4.7, -0.1, 1.6);
    g.add(tip);
  }

  const hstab = wing(
    [[-2.0, -0.7], [0, 0.7], [2.0, -0.7], [2.0, -1.3], [0, -1.0], [-2.0, -1.3]],
    0.14, dark
  );
  hstab.position.set(0, 0.05, 4.0);
  g.add(hstab);

  const fin = wing([[0, 1.6], [1.7, -0.3], [1.7, -1.0], [0, -1.2]], 0.14, red);
  fin.rotation.z = Math.PI / 2;
  fin.position.set(0, 0.4, 3.8);
  g.add(fin);

  const burner = burnerMesh(0.32, 1.8);
  burner.material.color.set(0xff7040);
  burner.position.set(0, 0, 3.9);
  g.add(burner);
  g.userData.burner = burner;

  return g;
}

export function buildModel(id) {
  switch (id) {
    case 'falcon': return buildFalcon();
    case 'mustang': return buildMustang();
    case 'nighthawk': return buildNighthawk();
    default: return buildEnemyModel();
  }
}

