import * as THREE from 'three';

const SKY_VERT = /* glsl */ `
  varying vec3 vPos;
  void main() {
    vPos = position;
    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  }
`;

const SKY_FRAG = /* glsl */ `
  varying vec3 vPos;
  uniform vec3 topColor;
  uniform vec3 horizonColor;
  uniform vec3 bottomColor;
  void main() {
    float h = normalize(vPos).y;
    vec3 col = h >= 0.0
      ? mix(horizonColor, topColor, smoothstep(0.0, 0.5, h))
      : mix(horizonColor, bottomColor, smoothstep(0.0, -0.25, h));
    gl_FragColor = vec4(col, 1.0);
  }
`;

export function makeSky(radius = 24000) {
  const mat = new THREE.ShaderMaterial({
    uniforms: {
      topColor: { value: new THREE.Color(0x3a6ca8) },
      horizonColor: { value: new THREE.Color(0xe8d9bc) },
      bottomColor: { value: new THREE.Color(0x6d8aa0) },
    },
    vertexShader: SKY_VERT,
    fragmentShader: SKY_FRAG,
    side: THREE.BackSide,
    fog: false,
    depthWrite: false,
  });
  const sky = new THREE.Mesh(new THREE.SphereGeometry(radius, 24, 16), mat);
  sky.renderOrder = -10;
  return sky;
}

export function addLights(scene) {
  const sun = new THREE.DirectionalLight(0xfff0d8, 2.4);
  sun.position.set(4000, 6000, 2500);
  scene.add(sun);
  scene.add(new THREE.HemisphereLight(0xbcd6f0, 0x4a5a48, 0.75));
  return sun;
}

function makeCloud(rng) {
  const group = new THREE.Group();
  const cmat = new THREE.MeshStandardMaterial({
    color: 0xf6f9fd, roughness: 1, metalness: 0, flatShading: true,
    transparent: true, opacity: 0.92,
  });
  const n = 4 + Math.floor(rng() * 4);
  for (let i = 0; i < n; i++) {
    const puff = new THREE.Mesh(new THREE.IcosahedronGeometry(1, 0), cmat);
    puff.position.set((rng() - 0.5) * 220, (rng() - 0.5) * 40, (rng() - 0.5) * 140);
    const s = 35 + rng() * 65;
    puff.scale.set(s * (1 + rng() * 0.6), s * 0.42, s);
    puff.rotation.y = rng() * Math.PI;
    group.add(puff);
  }
  return group;
}

export function buildWorld(scene) {
  // deterministic-ish rng so the world looks composed
  let seed = 1337;
  const rng = () => {
    seed = (seed * 16807) % 2147483647;
    return (seed - 1) / 2147483646;
  };

  scene.fog = new THREE.Fog(0xd7d4c3, 3500, 16000);
  scene.add(makeSky());
  addLights(scene);

  // sun disc
  const sunSprite = new THREE.Mesh(
    new THREE.CircleGeometry(900, 24),
    new THREE.MeshBasicMaterial({
      color: 0xffeebb, fog: false, transparent: true, opacity: 0.95,
      blending: THREE.AdditiveBlending, depthWrite: false,
    })
  );
  sunSprite.position.set(9000, 11000, 5600);
  sunSprite.lookAt(0, 0, 0);
  scene.add(sunSprite);

  // ocean
  const ocean = new THREE.Mesh(
    new THREE.PlaneGeometry(60000, 60000).rotateX(-Math.PI / 2),
    new THREE.MeshStandardMaterial({ color: 0x29597a, roughness: 0.8, metalness: 0.15 })
  );
  scene.add(ocean);

  // islands
  const sand = new THREE.MeshStandardMaterial({ color: 0xc9b98a, roughness: 1, flatShading: true });
  const green = new THREE.MeshStandardMaterial({ color: 0x5d7d4a, roughness: 1, flatShading: true });
  for (let i = 0; i < 34; i++) {
    const angle = rng() * Math.PI * 2;
    const dist = 1500 + rng() * 14000;
    const x = Math.cos(angle) * dist;
    const z = Math.sin(angle) * dist;
    const h = 80 + rng() * 380;
    const r = h * (1.8 + rng() * 1.6);

    const base = new THREE.Mesh(new THREE.ConeGeometry(r, h, 5 + Math.floor(rng() * 3)), sand);
    base.position.set(x, h / 2 - 4, z);
    base.rotation.y = rng() * Math.PI;
    scene.add(base);

    if (rng() > 0.3) {
      const top = new THREE.Mesh(new THREE.ConeGeometry(r * 0.55, h * 0.8, 5), green);
      top.position.set(x + (rng() - 0.5) * r * 0.3, h * 0.75, z + (rng() - 0.5) * r * 0.3);
      top.rotation.y = rng() * Math.PI;
      scene.add(top);
    }
  }

  // distant mountain ring for the horizon
  const rock = new THREE.MeshStandardMaterial({ color: 0x70809a, roughness: 1, flatShading: true });
  for (let i = 0; i < 14; i++) {
    const angle = (i / 14) * Math.PI * 2 + rng() * 0.4;
    const dist = 13000 + rng() * 3500;
    const h = 900 + rng() * 1400;
    const m = new THREE.Mesh(new THREE.ConeGeometry(h * 1.7, h, 6), rock);
    m.position.set(Math.cos(angle) * dist, h / 2, Math.sin(angle) * dist);
    m.rotation.y = rng() * Math.PI;
    scene.add(m);
  }

  // clouds
  for (let i = 0; i < 30; i++) {
    const cloud = makeCloud(rng);
    const angle = rng() * Math.PI * 2;
    const dist = rng() * 13000;
    cloud.position.set(Math.cos(angle) * dist, 900 + rng() * 1500, Math.sin(angle) * dist);
    scene.add(cloud);
  }
}

