import * as THREE from 'three';

const _seg = new THREE.Vector3();
const _toC = new THREE.Vector3();
const _pt = new THREE.Vector3();
const _look = new THREE.Vector3();

function segmentHitsSphere(p0, p1, center, radius) {
  _seg.subVectors(p1, p0);
  const len2 = _seg.lengthSq();
  let t = 0;
  if (len2 > 0) {
    t = THREE.MathUtils.clamp(_toC.subVectors(center, p0).dot(_seg) / len2, 0, 1);
  }
  _pt.copy(p0).addScaledVector(_seg, t);
  return _pt.distanceToSquared(center) <= radius * radius;
}

/**
 * Pooled tracer rounds. Every bullet renders as a glowing streak so
 * ammunition traces are always visible.
 */
export class BulletSystem {
  constructor(scene, capacity = 360) {
    this.scene = scene;
    this.pool = [];
    const geo = new THREE.BoxGeometry(0.35, 0.35, 7);
    for (let i = 0; i < capacity; i++) {
      const mesh = new THREE.Mesh(
        geo,
        new THREE.MeshBasicMaterial({
          color: 0xffffff, transparent: true, opacity: 0.95,
          blending: THREE.AdditiveBlending, depthWrite: false,
        })
      );
      mesh.visible = false;
      scene.add(mesh);
      this.pool.push({
        mesh,
        pos: new THREE.Vector3(),
        prev: new THREE.Vector3(),
        vel: new THREE.Vector3(),
        ttl: 0,
        dmg: 0,
        team: '',
        alive: false,
      });
    }
    this.cursor = 0;
  }

  fire(pos, vel, dmg, team, color) {
    const b = this.pool[this.cursor];
    this.cursor = (this.cursor + 1) % this.pool.length;
    b.pos.copy(pos);
    b.prev.copy(pos);
    b.vel.copy(vel);
    b.dmg = dmg;
    b.team = team;
    b.ttl = 2.2;
    b.alive = true;
    b.mesh.visible = true;
    b.mesh.material.color.set(color);
    b.mesh.position.copy(pos);
  }

  /** targets: [{ team, body, radius, onHit(dmg, point) }] */
  update(dt, targets) {
    for (const b of this.pool) {
      if (!b.alive) continue;
      b.prev.copy(b.pos);
      b.vel.y -= 9.81 * 0.35 * dt;
      b.pos.addScaledVector(b.vel, dt);
      b.ttl -= dt;

      if (b.ttl <= 0 || b.pos.y < 1) {
        this.kill(b);
        continue;
      }

      for (const t of targets) {
        if (t.team === b.team) continue;
        if (segmentHitsSphere(b.prev, b.pos, t.body.pos, t.radius)) {
          t.onHit(b.dmg, b.pos);
          this.kill(b);
          break;
        }
      }
      if (!b.alive) continue;

      b.mesh.position.copy(b.pos);
      _look.copy(b.pos).add(b.vel);
      b.mesh.lookAt(_look);
    }
  }

  kill(b) {
    b.alive = false;
    b.mesh.visible = false;
  }

  clear() {
    for (const b of this.pool) this.kill(b);
  }
}

