import * as THREE from 'three';

function makeParticleTexture() {
  const c = document.createElement('canvas');
  c.width = c.height = 64;
  const ctx = c.getContext('2d');
  const grad = ctx.createRadialGradient(32, 32, 0, 32, 32, 32);
  grad.addColorStop(0, 'rgba(255,255,255,1)');
  grad.addColorStop(0.4, 'rgba(255,255,255,0.6)');
  grad.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, 64, 64);
  return new THREE.CanvasTexture(c);
}

/** Pooled sprite particles: smoke trails, muzzle sparks, fireballs. */
export class Effects {
  constructor(scene, capacity = 520) {
    this.scene = scene;
    this.tex = makeParticleTexture();
    this.pool = [];
    this.free = [];
    for (let i = 0; i < capacity; i++) {
      const sprite = new THREE.Sprite(
        new THREE.SpriteMaterial({
          map: this.tex, transparent: true, depthWrite: false, opacity: 0,
        })
      );
      sprite.visible = false;
      scene.add(sprite);
      const p = {
        sprite,
        vel: new THREE.Vector3(),
        life: 0, maxLife: 1,
        size: 1, grow: 0,
        baseOpacity: 1,
        alive: false,
      };
      this.pool.push(p);
      this.free.push(p);
    }
  }

  spawn(pos, { vel = null, color = 0x888888, size = 4, life = 1.5, grow = 6, opacity = 0.5, additive = false }) {
    const p = this.free.pop();
    if (!p) return;
    p.alive = true;
    p.life = 0;
    p.maxLife = life;
    p.size = size;
    p.grow = grow;
    p.baseOpacity = opacity;
    p.sprite.visible = true;
    p.sprite.position.copy(pos);
    p.sprite.scale.setScalar(size);
    p.sprite.material.color.set(color);
    p.sprite.material.opacity = opacity;
    p.sprite.material.blending = additive ? THREE.AdditiveBlending : THREE.NormalBlending;
    if (vel) p.vel.copy(vel); else p.vel.set(0, 0, 0);
  }

  smokeTrail(pos, heavy) {
    this.spawn(pos, {
      color: heavy ? 0x1c1c1c : 0x555555,
      size: heavy ? 5 : 3.5,
      life: 1.4 + Math.random() * 0.5,
      grow: heavy ? 9 : 6,
      opacity: heavy ? 0.55 : 0.4,
      vel: new THREE.Vector3((Math.random() - 0.5) * 4, 6 + Math.random() * 4, (Math.random() - 0.5) * 4),
    });
    if (heavy) {
      this.spawn(pos, {
        color: 0xff8830, size: 2.4, life: 0.3, grow: 2, opacity: 0.9, additive: true,
      });
    }
  }

  sparks(pos) {
    for (let i = 0; i < 5; i++) {
      this.spawn(pos, {
        color: 0xffcc66, size: 1.6, life: 0.3 + Math.random() * 0.2, grow: -2,
        opacity: 0.95, additive: true,
        vel: new THREE.Vector3(
          (Math.random() - 0.5) * 90, (Math.random() - 0.5) * 90, (Math.random() - 0.5) * 90
        ),
      });
    }
  }

  explosion(pos, scale = 1) {
    this.spawn(pos, { color: 0xffffff, size: 26 * scale, life: 0.22, grow: 70, opacity: 1, additive: true });
    for (let i = 0; i < 12; i++) {
      this.spawn(pos, {
        color: i % 2 ? 0xff9344 : 0xff5522,
        size: (6 + Math.random() * 8) * scale,
        life: 0.5 + Math.random() * 0.4,
        grow: 18 * scale, opacity: 0.95, additive: true,
        vel: new THREE.Vector3(
          (Math.random() - 0.5) * 70, (Math.random() - 0.3) * 60, (Math.random() - 0.5) * 70
        ).multiplyScalar(scale),
      });
    }
    for (let i = 0; i < 14; i++) {
      this.spawn(pos, {
        color: 0x2a2a2a,
        size: (8 + Math.random() * 10) * scale,
        life: 1.6 + Math.random() * 1.2,
        grow: 12 * scale, opacity: 0.55,
        vel: new THREE.Vector3(
          (Math.random() - 0.5) * 45, 10 + Math.random() * 30, (Math.random() - 0.5) * 45
        ).multiplyScalar(scale),
      });
    }
    for (let i = 0; i < 16; i++) {
      this.spawn(pos, {
        color: 0xffd27a, size: 1.8, life: 0.5 + Math.random() * 0.4, grow: -1.5,
        opacity: 1, additive: true,
        vel: new THREE.Vector3(
          (Math.random() - 0.5) * 240, (Math.random() - 0.2) * 200, (Math.random() - 0.5) * 240
        ).multiplyScalar(scale * 0.8),
      });
    }
  }

  update(dt) {
    for (const p of this.pool) {
      if (!p.alive) continue;
      p.life += dt;
      if (p.life >= p.maxLife) {
        p.alive = false;
        p.sprite.visible = false;
        p.sprite.material.opacity = 0;
        this.free.push(p);
        continue;
      }
      const t = p.life / p.maxLife;
      p.sprite.position.addScaledVector(p.vel, dt);
      p.vel.multiplyScalar(1 - 1.6 * dt);
      const s = Math.max(0.1, p.size + p.grow * t);
      p.sprite.scale.setScalar(s);
      p.sprite.material.opacity = p.baseOpacity * (1 - t);
    }
  }

  clear() {
    for (const p of this.pool) {
      if (p.alive) {
        p.alive = false;
        p.sprite.visible = false;
        this.free.push(p);
      }
    }
  }
}

