/** Minimal synthesized sound: engine hum, gunfire, hits, explosions. */
class AudioSys {
  constructor() {
    this.ctx = null;
    this.lastGun = 0;
  }

  unlock() {
    try {
      if (!this.ctx) {
        this.ctx = new (window.AudioContext || window.webkitAudioContext)();
        this.master = this.ctx.createGain();
        this.master.gain.value = 0.32;
        this.master.connect(this.ctx.destination);

        const len = this.ctx.sampleRate;
        this.noiseBuf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
        const data = this.noiseBuf.getChannelData(0);
        for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
      }
      this.ctx.resume();
    } catch { /* audio unavailable */ }
  }

  startEngine() {
    if (!this.ctx || this.engineGain) return;
    try {
      this.engineOsc = this.ctx.createOscillator();
      this.engineOsc.type = 'sawtooth';
      this.engineOsc.frequency.value = 70;
      this.engineOsc2 = this.ctx.createOscillator();
      this.engineOsc2.type = 'sawtooth';
      this.engineOsc2.frequency.value = 71.5;
      this.engineFilter = this.ctx.createBiquadFilter();
      this.engineFilter.type = 'lowpass';
      this.engineFilter.frequency.value = 400;
      this.engineGain = this.ctx.createGain();
      this.engineGain.gain.value = 0;
      this.engineOsc.connect(this.engineFilter);
      this.engineOsc2.connect(this.engineFilter);
      this.engineFilter.connect(this.engineGain);
      this.engineGain.connect(this.master);
      this.engineOsc.start();
      this.engineOsc2.start();
    } catch { /* ignore */ }
  }

  setEngine(throttle, speedFrac) {
    if (!this.engineGain) return;
    const t = this.ctx.currentTime;
    this.engineOsc.frequency.setTargetAtTime(55 + throttle * 70 + speedFrac * 30, t, 0.1);
    this.engineOsc2.frequency.setTargetAtTime(56 + throttle * 72 + speedFrac * 30, t, 0.1);
    this.engineFilter.frequency.setTargetAtTime(250 + throttle * 1100, t, 0.1);
    this.engineGain.gain.setTargetAtTime(0.04 + throttle * 0.05, t, 0.1);
  }

  stopEngine() {
    if (!this.engineGain) return;
    try {
      this.engineOsc.stop();
      this.engineOsc2.stop();
    } catch { /* ignore */ }
    this.engineOsc = this.engineOsc2 = this.engineFilter = this.engineGain = null;
  }

  gun() {
    if (!this.ctx) return;
    const now = performance.now();
    if (now - this.lastGun < 35) return;
    this.lastGun = now;
    try {
      const src = this.ctx.createBufferSource();
      src.buffer = this.noiseBuf;
      const bp = this.ctx.createBiquadFilter();
      bp.type = 'bandpass';
      bp.frequency.value = 1700;
      bp.Q.value = 0.8;
      const g = this.ctx.createGain();
      const t = this.ctx.currentTime;
      g.gain.setValueAtTime(0.5, t);
      g.gain.exponentialRampToValueAtTime(0.01, t + 0.07);
      src.connect(bp).connect(g).connect(this.master);
      src.start(t, Math.random(), 0.08);
    } catch { /* ignore */ }
  }

  hit() {
    if (!this.ctx) return;
    try {
      const osc = this.ctx.createOscillator();
      osc.type = 'square';
      osc.frequency.value = 520;
      const g = this.ctx.createGain();
      const t = this.ctx.currentTime;
      g.gain.setValueAtTime(0.12, t);
      g.gain.exponentialRampToValueAtTime(0.01, t + 0.05);
      osc.connect(g).connect(this.master);
      osc.start(t);
      osc.stop(t + 0.06);
    } catch { /* ignore */ }
  }

  explosion() {
    if (!this.ctx) return;
    try {
      const src = this.ctx.createBufferSource();
      src.buffer = this.noiseBuf;
      const lp = this.ctx.createBiquadFilter();
      lp.type = 'lowpass';
      const t = this.ctx.currentTime;
      lp.frequency.setValueAtTime(900, t);
      lp.frequency.exponentialRampToValueAtTime(80, t + 1.2);
      const g = this.ctx.createGain();
      g.gain.setValueAtTime(0.8, t);
      g.gain.exponentialRampToValueAtTime(0.01, t + 1.3);
      src.connect(lp).connect(g).connect(this.master);
      src.start(t, Math.random() * 0.5, 1.4);

      const thump = this.ctx.createOscillator();
      thump.type = 'sine';
      thump.frequency.setValueAtTime(85, t);
      thump.frequency.exponentialRampToValueAtTime(30, t + 0.5);
      const tg = this.ctx.createGain();
      tg.gain.setValueAtTime(0.6, t);
      tg.gain.exponentialRampToValueAtTime(0.01, t + 0.55);
      thump.connect(tg).connect(this.master);
      thump.start(t);
      thump.stop(t + 0.6);
    } catch { /* ignore */ }
  }
}

export const audio = new AudioSys();

