const _muzzle = new THREE.Vector3();
const _bVel = new THREE.Vector3();
const _toMe = new THREE.Vector3();
const _smokePos = new THREE.Vector3();

export class Enemy {
  constructor(scene, level, pos, heading) {
    this.spec = enemySpec(level);
    this.body = new FlightBody(this.spec);
    this.body.pos.copy(pos);
    this.body.quat.setFromAxisAngle(new THREE.Vector3(0, 1, 0), heading);
    this.body.speed = this.spec.maxSpeed * 0.6;
    this.body.throttle = 0.85;

    this.model = buildEnemyModel();
    scene.add(this.model);

    this.aimError = Math.max(0.12, 0.85 - level * 0.09);
    this.fireTimer = Math.random() * 2;
    this.jinkTimer = 0;
    this.jinkDir = 1;
    this.jinkCooldown = Math.random() * 3;
    this.wobble = Math.random() * 100;
    this.smokeTimer = 0;
    this.ctl = { pitch: 0, roll: 0, yaw: 0 };
  }

  damage(d) {
    this.body.hp -= d;
    // getting hit triggers an evasive break
    if (this.jinkTimer <= 0 && Math.random() < 0.5) {
      this.startJink();
    }
  }

  startJink() {
    this.jinkTimer = 1.2 + Math.random() * 0.8;
    this.jinkDir = Math.random() < 0.5 ? -1 : 1;
  }

  update(dt, player, bullets, effects, time) {
    const b = this.body;
    const ctl = this.ctl;
    ctl.pitch = 0; ctl.roll = 0; ctl.yaw = 0;

    this.jinkCooldown -= dt;
    if (this.jinkTimer > 0) this.jinkTimer -= dt;

    const dist = b.pos.distanceTo(player.pos);

    // does the player have our six? break if close behind
    if (this.jinkTimer <= 0 && this.jinkCooldown <= 0 && dist < 700) {
      _toMe.subVectors(b.pos, player.pos).normalize();
      const playerAim = player.forward(_aim).dot(_toMe);
      if (playerAim > 0.92) {
        this.startJink();
        this.jinkCooldown = 4 + Math.random() * 3;
      }
    }

    // aim point: lead the player, degraded by skill-based wander
    const tof = dist / this.spec.bulletSpeed;
    _aim.copy(player.pos).addScaledVector(player.vel, tof);
    const wob = this.aimError * dist * 0.06;
    _aim.x += Math.sin(time * 1.7 + this.wobble) * wob;
    _aim.y += Math.cos(time * 2.3 + this.wobble) * wob;
    _aim.z += Math.sin(time * 1.3 + this.wobble * 2) * wob;

    _invQ.copy(b.quat).invert();
    _local.copy(_aim).sub(b.pos).applyQuaternion(_invQ);
    const angleOff = Math.atan2(Math.hypot(_local.x, _local.y), -_local.z);

    if (b.pos.y < 220 && b.vel.y < 20) {
      // ground avoidance overrides everything: roll level, pull up
      const rollErr = this.levelRollError();
      ctl.roll = THREE.MathUtils.clamp(rollErr * 2.5, -1, 1);
      ctl.pitch = 1;
      b.throttle = 1;
    } else if (this.jinkTimer > 0) {
      ctl.roll = this.jinkDir;
      ctl.pitch = 0.85;
      b.throttle = 1;
    } else {
      const rollErr = Math.atan2(_local.x, _local.y);
      ctl.roll = THREE.MathUtils.clamp(rollErr * 1.8, -1, 1);
      const aligned = Math.abs(rollErr) < 1.1 || _local.z > 0;
      ctl.pitch = THREE.MathUtils.clamp(angleOff * 3 * (aligned ? 1 : 0.25), 0, 1);
      ctl.yaw = THREE.MathUtils.clamp(_local.x / Math.max(dist, 1) * 4, -0.4, 0.4);
      b.throttle = dist > 700 ? 1 : dist < 280 ? 0.55 : 0.8;
    }

    b.step(dt, ctl);

    // guns
    this.fireTimer -= dt;
    if (this.fireTimer <= 0 && angleOff < 0.1 && dist < 1100 && player.hp > 0) {
      this.fireTimer = this.spec.fireInterval;
      const fwd = b.forward(_bVel);
      for (const m of this.spec.guns) {
        _muzzle.set(m[0], m[1], m[2]).applyQuaternion(b.quat).add(b.pos);
        _bVel.copy(fwd).multiplyScalar(b.speed + this.spec.bulletSpeed);
        _bVel.x += (Math.random() - 0.5) * 14;
        _bVel.y += (Math.random() - 0.5) * 14;
        _bVel.z += (Math.random() - 0.5) * 14;
        bullets.fire(_muzzle, _bVel, this.spec.gunDamage, 'enemy', this.spec.tracerColor);
      }
    }

    // damage smoke
    const hpFrac = b.hp / b.maxHp;
    if (hpFrac < 0.5) {
      this.smokeTimer -= dt;
      if (this.smokeTimer <= 0) {
        this.smokeTimer = 0.05;
        _smokePos.set(0, 0, 3.5).applyQuaternion(b.quat).add(b.pos);
        effects.smokeTrail(_smokePos, hpFrac < 0.22);
      }
    }

    this.model.position.copy(b.pos);
    this.model.quaternion.copy(b.quat);
    if (this.model.userData.burner) {
      this.model.userData.burner.scale.z = 0.3 + b.throttle * 0.9;
    }
  }

  levelRollError() {
    // roll error that brings wings level (lift vector up)
    const up = this.body.up(_toMe);
    const right = _aim.set(1, 0, 0).applyQuaternion(this.body.quat);
    return Math.atan2(-right.y, up.y);
  }

  dispose(scene) {
    scene.remove(this.model);
  }
}

