export class Input {
  constructor() {
    this.keys = new Set();
    this.onEscape = null;
    window.addEventListener('keydown', (e) => {
      if (e.code === 'Escape' && this.onEscape) this.onEscape();
      this.keys.add(e.code);
      if (['Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(e.code)) {
        e.preventDefault();
      }
    });
    window.addEventListener('keyup', (e) => this.keys.delete(e.code));
    window.addEventListener('blur', () => this.keys.clear());
    this.mouseDown = false;
    window.addEventListener('mousedown', (e) => { if (e.button === 0) this.mouseDown = true; });
    window.addEventListener('mouseup', (e) => { if (e.button === 0) this.mouseDown = false; });
  }

  axis(negCodes, posCodes) {
    let v = 0;
    for (const c of negCodes) if (this.keys.has(c)) { v -= 1; break; }
    for (const c of posCodes) if (this.keys.has(c)) { v += 1; break; }
    return v;
  }

  get pitch() { return this.axis(['KeyS', 'ArrowDown'], ['KeyW', 'ArrowUp']); }
  get roll() { return this.axis(['KeyA', 'ArrowLeft'], ['KeyD', 'ArrowRight']); }
  get yaw() { return this.axis(['KeyQ'], ['KeyE']); }
  get throttleUp() { return this.keys.has('ShiftLeft') || this.keys.has('ShiftRight'); }
  get throttleDown() { return this.keys.has('ControlLeft') || this.keys.has('ControlRight'); }
  get fire() { return this.keys.has('Space') || this.mouseDown; }
}

