import * as THREE from 'three';

const _fwd = new THREE.Vector3();

export class HUD {
  constructor() {
    this.root = document.getElementById('hud');
    this.elSpeed = document.getElementById('hud-speed');
    this.elAlt = document.getElementById('hud-alt');
    this.elThr = document.getElementById('hud-thr');
    this.elHp = document.getElementById('hud-hp');
    this.elRound = document.getElementById('hud-round');
    this.elEnemies = document.getElementById('hud-enemies');
    this.hitmarker = document.getElementById('hitmarker');
    this.vignette = document.getElementById('vignette');
    this.hint = document.getElementById('hud-hint');
    this.radar = document.getElementById('radar');
    this.radarCtx = this.radar.getContext('2d');
    this.banner = document.getElementById('banner');
    this.bannerTitle = document.getElementById('banner-title');
    this.bannerSub = document.getElementById('banner-sub');

    this.hitFlash = 0;
    this.dmgFlash = 0;
    this.hintTimer = 0;
    this.bannerTimer = 0;
  }

  show() {
    this.root.classList.remove('hidden');
    this.hint.style.opacity = '1';
    this.hintTimer = 8;
  }

  hide() {
    this.root.classList.add('hidden');
    this.hideBanner();
  }

  setRound(round, enemies) {
    this.elRound.textContent = round;
    this.elEnemies.textContent = enemies;
  }

  flashHit() { this.hitFlash = 0.25; }
  flashDamage() { this.dmgFlash = 0.5; }

  showBanner(title, sub, red = false, duration = 2.6) {
    this.bannerTitle.textContent = title;
    this.bannerSub.textContent = sub;
    this.banner.classList.toggle('red', red);
    this.banner.classList.remove('hidden');
    this.bannerTimer = duration;
  }

  hideBanner() {
    this.banner.classList.add('hidden');
    this.bannerTimer = 0;
  }

  update(dt, player, enemies) {
    this.elSpeed.textContent = Math.round(player.speed * 3.6);
    this.elAlt.textContent = Math.max(0, Math.round(player.pos.y));
    this.elThr.style.width = `${Math.round(player.throttle * 100)}%`;

    const hpFrac = Math.max(0, player.hp / player.maxHp);
    this.elHp.style.width = `${hpFrac * 100}%`;
    this.elHp.style.background = hpFrac > 0.5 ? '#58d68d' : hpFrac > 0.25 ? '#f5b041' : '#e74c3c';

    this.elEnemies.textContent = enemies.length;

    if (this.hitFlash > 0) {
      this.hitFlash -= dt;
      this.hitmarker.style.opacity = Math.max(0, this.hitFlash / 0.25);
    }
    if (this.dmgFlash > 0) {
      this.dmgFlash -= dt;
      this.vignette.style.opacity = Math.max(0, this.dmgFlash / 0.5);
    }
    if (this.hintTimer > 0) {
      this.hintTimer -= dt;
      if (this.hintTimer <= 0) this.hint.style.opacity = '0';
    }
    if (this.bannerTimer > 0) {
      this.bannerTimer -= dt;
      if (this.bannerTimer <= 0) this.hideBanner();
    }

    this.drawRadar(player, enemies);
  }

  drawRadar(player, enemies) {
    const ctx = this.radarCtx;
    const S = 150, C = S / 2, RANGE = 4000;
    ctx.clearRect(0, 0, S, S);

    ctx.strokeStyle = 'rgba(111,211,255,0.25)';
    ctx.lineWidth = 1;
    for (const r of [0.33, 0.66, 1]) {
      ctx.beginPath();
      ctx.arc(C, C, (C - 4) * r, 0, Math.PI * 2);
      ctx.stroke();
    }
    ctx.beginPath();
    ctx.moveTo(C, 4); ctx.lineTo(C, S - 4);
    ctx.moveTo(4, C); ctx.lineTo(S - 4, C);
    ctx.stroke();

    player.forward(_fwd);
    const heading = Math.atan2(_fwd.x, -_fwd.z);
    const cos = Math.cos(-heading), sin = Math.sin(-heading);

    for (const e of enemies) {
      const dx = e.body.pos.x - player.pos.x;
      const dz = e.body.pos.z - player.pos.z;
      // rotate so player heading points up
      const rx = dx * cos - dz * sin;
      const rz = dx * sin + dz * cos;
      const px = C + (rx / RANGE) * (C - 6);
      const py = C + (rz / RANGE) * (C - 6);
      if (px < 3 || px > S - 3 || py < 3 || py > S - 3) {
        // clamp to edge as a dimmer blip
        const ang = Math.atan2(py - C, px - C);
        ctx.fillStyle = 'rgba(255,90,74,0.45)';
        ctx.beginPath();
        ctx.arc(C + Math.cos(ang) * (C - 6), C + Math.sin(ang) * (C - 6), 2.5, 0, Math.PI * 2);
        ctx.fill();
      } else {
        ctx.fillStyle = '#ff5a4a';
        ctx.beginPath();
        ctx.arc(px, py, 3.2, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    // player marker
    ctx.fillStyle = '#6fd3ff';
    ctx.beginPath();
    ctx.moveTo(C, C - 6);
    ctx.lineTo(C - 4, C + 5);
    ctx.lineTo(C + 4, C + 5);
    ctx.closePath();
    ctx.fill();
  }
}

