import * as THREE from 'three';
import { PLANES, buildModel } from './planes.js';
import { makeSky, addLights } from './world.js';

export class Menu {
  constructor(renderer, onStart) {
    this.renderer = renderer;
    this.onStart = onStart;
    this.active = false;
    this.time = 0;

    this.scene = new THREE.Scene();
    this.scene.add(makeSky(2000));
    addLights(this.scene);
    const rim = new THREE.DirectionalLight(0x6fd3ff, 1.6);
    rim.position.set(-30, 8, -40);
    this.scene.add(rim);

    // a few clouds drifting below the showcase plane
    const cloudMat = new THREE.MeshStandardMaterial({
      color: 0xf6f9fd, roughness: 1, flatShading: true, transparent: true, opacity: 0.85,
    });
    for (let i = 0; i < 7; i++) {
      const puff = new THREE.Mesh(new THREE.IcosahedronGeometry(1, 0), cloudMat);
      const a = (i / 7) * Math.PI * 2;
      puff.position.set(Math.cos(a) * (26 + i * 4), -9 - (i % 3) * 3, Math.sin(a) * (26 + i * 4));
      puff.scale.set(10 + i * 2, 3.5, 7 + i);
      this.scene.add(puff);
    }

    this.camera = new THREE.PerspectiveCamera(40, innerWidth / innerHeight, 0.1, 5000);
    this.camera.position.set(11, 4, 15);
    this.camera.lookAt(0, 0, 0);

    this.holder = new THREE.Group();
    this.scene.add(this.holder);
    this.previewModel = null;

    this.buildDom();
    this.select(0);
  }

  buildDom() {
    const menu = document.getElementById('menu');
    menu.innerHTML = `
      <h1>SKYFALL</h1>
      <div class="subtitle">Ace Duel — Select Your Aircraft</div>
      <div class="menu-body">
        <div class="cards" id="cards"></div>
        <div class="menu-spacer"></div>
        <div class="stats-panel">
          <h2 id="stat-name"></h2>
          <div class="stat-type" id="stat-type"></div>
          <div class="stat-desc" id="stat-desc"></div>
          <div id="stat-bars"></div>
          <table class="spec-table" id="spec-table"></table>
          <button id="start-btn">TAKE OFF</button>
        </div>
      </div>
      <div class="controls-hint">
        W/S pitch · A/D roll · Q/E yaw · SHIFT/CTRL throttle · SPACE fire · ESC abort sortie
      </div>
    `;

    const cards = menu.querySelector('#cards');
    PLANES.forEach((p, i) => {
      const card = document.createElement('div');
      card.className = 'plane-card';
      card.innerHTML = `
        <div class="card-name">${p.name}</div>
        <div class="card-type" style="color:#${p.tracerColor.toString(16).padStart(6, '0')}">${p.type}</div>
      `;
      card.addEventListener('click', () => this.select(i));
      cards.appendChild(card);
    });

    menu.querySelector('#start-btn').addEventListener('click', () => {
      this.onStart(PLANES[this.idx]);
    });

    this.el = menu;
    this.elName = menu.querySelector('#stat-name');
    this.elType = menu.querySelector('#stat-type');
    this.elDesc = menu.querySelector('#stat-desc');
    this.elBars = menu.querySelector('#stat-bars');
    this.elSpecs = menu.querySelector('#spec-table');
    this.cardEls = [...cards.children];
  }

  select(i) {
    this.idx = i;
    const p = PLANES[i];

    this.cardEls.forEach((c, j) => c.classList.toggle('active', j === i));
    this.elName.textContent = p.name;
    this.elType.textContent = p.type;
    this.elDesc.textContent = p.desc;

    this.elBars.innerHTML = '';
    for (const [label, v] of Object.entries(p.bars)) {
      const row = document.createElement('div');
      row.className = 'bar-row';
      row.innerHTML = `
        <div class="bar-label">${label}</div>
        <div class="bar-track"><div class="bar-fill" style="width:0%"></div></div>
      `;
      this.elBars.appendChild(row);
      requestAnimationFrame(() => {
        row.querySelector('.bar-fill').style.width = `${v * 100}%`;
      });
    }

    this.elSpecs.innerHTML = p.specs
      .map(([k, v]) => `<tr><td>${k}</td><td>${v}</td></tr>`)
      .join('');

    if (this.previewModel) this.holder.remove(this.previewModel);
    this.previewModel = buildModel(p.id);
    this.holder.add(this.previewModel);
  }

  show() {
    this.active = true;
    this.el.classList.remove('hidden');
  }

  hide() {
    this.active = false;
    this.el.classList.add('hidden');
  }

  resize() {
    this.camera.aspect = innerWidth / innerHeight;
    this.camera.updateProjectionMatrix();
  }

  update(dt) {
    this.time += dt;
    this.holder.rotation.y += dt * 0.35;
    this.holder.position.y = Math.sin(this.time * 0.8) * 0.4;
    if (this.previewModel?.userData.prop) {
      this.previewModel.userData.prop.rotation.z += dt * 18;
    }
    this.renderer.render(this.scene, this.camera);
  }
}

