import * as THREE from 'three';
import { FlightBody } from './flight.js';
import { buildModel } from './planes.js';
import { buildWorld } from './world.js';
import { BulletSystem } from './bullets.js';
import { Effects } from './effects.js';
import { Enemy } from './enemy.js';
import { Input } from './input.js';
import { HUD } from './hud.js';
import { audio } from './audio.js';

const WORLD_UP = new THREE.Vector3(0, 1, 0);
const _fwd = new THREE.Vector3();
const _up = new THREE.Vector3();
const _camDesired = new THREE.Vector3();
const _lookTarget = new THREE.Vector3();
const _muzzle = new THREE.Vector3();
const _bVel = new THREE.Vector3();
const _smokePos = new THREE.Vector3();

export class Game {
  constructor(renderer, callbacks) {
    this.renderer = renderer;
    this.cb = callbacks;

    this.scene = new THREE.Scene();
    buildWorld(this.scene);

    this.camera = new THREE.PerspectiveCamera(60, innerWidth / innerHeight, 0.5, 40000);
    this.bullets = new BulletSystem(this.scene);
    this.effects = new Effects(this.scene);
    this.hud = new HUD();
    this.input = new Input();
    this.input.onEscape = () => {
      if (this.state === 'playing' || this.state === 'clear') this.cb.onAbort();
    };

    this.enemies = [];
    this.state = 'idle';
    this.time = 0;
    this.shake = 0;
    this.camPos = new THREE.Vector3();
  }

  start(spec) {
    this.spec = spec;
    this.round = 1;

    this.player = new FlightBody(spec);
    this.player.pos.set(0, 1300, 0);
    this.player.speed = spec.maxSpeed * 0.6;

    this.model = buildModel(spec.id);
    this.scene.add(this.model);

    this.fireTimer = 0;
    this.smokeTimer = 0;
    this.clearTimer = 0;
    this.state = 'playing';

    this.hud.show();
    audio.startEngine();

    this.startRound();

    // snap camera behind the plane
    this.player.forward(_fwd);
    this.camPos.copy(this.player.pos)
      .addScaledVector(_fwd, -spec.camDist)
      .addScaledVector(WORLD_UP, spec.camHeight);
  }

  startRound() {
    const count = Math.min(9, 2 + this.round + (Math.random() < 0.4 ? 1 : 0));
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      const dist = 1700 + Math.random() * 1300;
      const pos = new THREE.Vector3(
        this.player.pos.x + Math.cos(angle) * dist,
        THREE.MathUtils.clamp(this.player.pos.y + (Math.random() - 0.5) * 800, 500, 2400),
        this.player.pos.z + Math.sin(angle) * dist
      );
      this.enemies.push(new Enemy(this.scene, this.round, pos, Math.random() * Math.PI * 2));
    }
    this.hud.setRound(this.round, count);
    this.hud.showBanner(`ROUND ${this.round}`, `${count} HOSTILES INBOUND`);
  }

  stop() {
    for (const e of this.enemies) e.dispose(this.scene);
    this.enemies.length = 0;
    if (this.model) {
      this.scene.remove(this.model);
      this.model = null;
    }
    this.bullets.clear();
    this.effects.clear();
    this.hud.hide();
    audio.stopEngine();
    this.state = 'idle';
  }

  killPlayer() {
    if (this.state !== 'playing' && this.state !== 'clear') return;
    this.state = 'dying';
    this.hud.showBanner('SHOT DOWN', 'AIRFRAME CRITICAL', true, 6);
    audio.setEngine(0, 0);
  }

  playerHit(dmg, point) {
    if (this.state !== 'playing' && this.state !== 'clear') return;
    this.player.hp -= dmg;
    this.effects.sparks(point);
    this.hud.flashDamage();
    this.shake = Math.min(this.shake + 0.4, 1.2);
    audio.hit();
    if (this.player.hp <= 0) this.killPlayer();
  }

  update(dt) {
    if (this.state === 'idle') return;
    this.time += dt;
    const p = this.player;

    if (this.state === 'playing' || this.state === 'clear') {
      this.updatePlaying(dt);
    } else if (this.state === 'dying') {
      this.updateDying(dt);
    }

    // shared sim updates
    const targets = this.buildTargets();
    this.bullets.update(dt, targets);
    this.effects.update(dt);

    // sync player model
    if (this.model) {
      this.model.position.copy(p.pos);
      this.model.quaternion.copy(p.quat);
      if (this.model.userData.prop) {
        this.model.userData.prop.rotation.z += dt * (8 + p.throttle * 45);
      }
      if (this.model.userData.burner) {
        this.model.userData.burner.scale.z = 0.25 + p.throttle * (this.state === 'dying' ? 0.1 : 1);
      }
    }

    this.updateCamera(dt);
    if (this.state !== 'idle') {
      this.hud.update(dt, p, this.enemies);
    }
    this.renderer.render(this.scene, this.camera);
  }

  updatePlaying(dt) {
    const p = this.player;
    const input = this.input;

    // throttle
    if (input.throttleUp) p.throttle = Math.min(1, p.throttle + dt * 0.6);
    if (input.throttleDown) p.throttle = Math.max(0, p.throttle - dt * 0.6);

    p.step(dt, { pitch: input.pitch, roll: input.roll, yaw: input.yaw });
    audio.setEngine(p.throttle, p.speed / this.spec.maxSpeed);

    // guns
    this.fireTimer -= dt;
    if (input.fire && this.fireTimer <= 0) {
      this.fireTimer = this.spec.fireInterval;
      p.forward(_fwd);
      for (const m of this.spec.guns) {
        _muzzle.set(m[0], m[1], m[2]).applyQuaternion(p.quat).add(p.pos);
        _bVel.copy(_fwd).multiplyScalar(p.speed + this.spec.bulletSpeed);
        _bVel.x += (Math.random() - 0.5) * 8;
        _bVel.y += (Math.random() - 0.5) * 8;
        _bVel.z += (Math.random() - 0.5) * 8;
        this.bullets.fire(_muzzle, _bVel, this.spec.gunDamage, 'player', this.spec.tracerColor);
      }
      audio.gun();
    }

    // player damage smoke
    const hpFrac = p.hp / p.maxHp;
    if (hpFrac < 0.5) {
      this.smokeTimer -= dt;
      if (this.smokeTimer <= 0) {
        this.smokeTimer = 0.05;
        _smokePos.set(0, 0, 4).applyQuaternion(p.quat).add(p.pos);
        this.effects.smokeTrail(_smokePos, hpFrac < 0.22);
      }
    }

    // enemies
    for (let i = this.enemies.length - 1; i >= 0; i--) {
      const e = this.enemies[i];
      e.update(dt, p, this.bullets, this.effects, this.time);
      if (e.body.hp <= 0 || e.body.pos.y < 8) {
        this.effects.explosion(e.body.pos, 1.4);
        audio.explosion();
        e.dispose(this.scene);
        this.enemies.splice(i, 1);
        this.hud.flashHit();
      }
    }

    // ground collision kills instantly
    if (p.pos.y < 8) {
      this.killPlayer();
      return;
    }

    // round flow
    if (this.state === 'playing' && this.enemies.length === 0) {
      this.state = 'clear';
      this.clearTimer = 3;
      this.hud.showBanner('ROUND CLEAR', 'REINFORCEMENTS INBOUND', false, 2.6);
    } else if (this.state === 'clear') {
      this.clearTimer -= dt;
      if (this.clearTimer <= 0) {
        this.round += 1;
        this.player.hp = Math.min(this.player.maxHp, this.player.hp + 35);
        this.state = 'playing';
        this.startRound();
      }
    }
  }

  updateDying(dt) {
    const p = this.player;
    p.stepDying(dt);

    // burning wreck trail
    this.smokeTimer -= dt;
    if (this.smokeTimer <= 0) {
      this.smokeTimer = 0.04;
      _smokePos.set(0, 0, 3).applyQuaternion(p.quat).add(p.pos);
      this.effects.smokeTrail(_smokePos, true);
    }

    // remaining enemies keep flying (but stop shooting at a dead man)
    for (const e of this.enemies) {
      e.update(dt, p, this.bullets, this.effects, this.time);
    }

    if (p.pos.y < 8) {
      p.pos.y = 8;
      this.effects.explosion(p.pos, 2.2);
      audio.explosion();
      if (this.model) this.model.visible = false;
      this.state = 'crashed';
      this.crashTimer = 0.9;
    }
  }

  buildTargets() {
    const targets = [];
    if (this.state === 'playing' || this.state === 'clear') {
      targets.push({
        team: 'player',
        body: this.player,
        radius: 7,
        onHit: (dmg, point) => this.playerHit(dmg, point),
      });
    }
    for (const e of this.enemies) {
      targets.push({
        team: 'enemy',
        body: e.body,
        radius: 7,
        onHit: (dmg, point) => {
          e.damage(dmg);
          this.effects.sparks(point);
          this.hud.flashHit();
          audio.hit();
        },
      });
    }
    return targets;
  }

  updateCamera(dt) {
    const p = this.player;
    p.forward(_fwd);
    p.up(_up);

    _camDesired.copy(p.pos)
      .addScaledVector(_fwd, -this.spec.camDist)
      .addScaledVector(_up, this.spec.camHeight);

    const k = 1 - Math.exp(-7 * dt);
    this.camPos.lerp(_camDesired, k);

    if (this.shake > 0) {
      this.shake = Math.max(0, this.shake - dt * 2.5);
      this.camPos.x += (Math.random() - 0.5) * this.shake;
      this.camPos.y += (Math.random() - 0.5) * this.shake;
      this.camPos.z += (Math.random() - 0.5) * this.shake;
    }

    this.camera.position.copy(this.camPos);
    this.camera.up.copy(_up).lerp(WORLD_UP, 0.55).normalize();
    _lookTarget.copy(p.pos).addScaledVector(_fwd, 40);
    this.camera.lookAt(_lookTarget);

    const targetFov = 58 + 14 * (p.speed / this.spec.maxSpeed);
    if (Math.abs(this.camera.fov - targetFov) > 0.1) {
      this.camera.fov += (targetFov - this.camera.fov) * Math.min(1, dt * 4);
      this.camera.updateProjectionMatrix();
    }
  }

  /** crashed-state timer: lets the fireball read before the blackout */
  tickCrash(dt) {
    if (this.state !== 'crashed') return false;
    this.crashTimer -= dt;
    if (this.crashTimer <= 0) {
      this.state = 'gameover';
      return true;
    }
    return false;
  }

  resize() {
    this.camera.aspect = innerWidth / innerHeight;
    this.camera.updateProjectionMatrix();
  }
}

