    game.stop();
    menu.show();
    state = 'menu';
  },
});

const menu = new Menu(renderer, (spec) => {
  audio.unlock();
  menu.hide();
  game.start(spec);
  state = 'game';
});

menu.show();

let last = performance.now();
renderer.setAnimationLoop((t) => {
  const dt = Math.min((t - last) / 1000, 0.05);
  last = t;
  if (state === 'menu') {
    menu.update(dt);
  } else {
    game.update(dt);
  }
});

window.addEventListener('resize', () => {
  renderer.setSize(innerWidth, innerHeight);
  menu.resize();
  game.resize();
});

